INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_site_section_home_hero_r1', 'vi', '{"title":"Tôi thiết kế website giúp doanh nghiệp được tin tưởng và được chọn rồi xây hệ thống để lớn lên.","eyebrow":"Thiết kế website · Phát triển SaaS · Full-stack","excerpt":"Từ landing page tập trung chuyển đổi đến SaaS đa tenant có backend phức tạp, tôi đồng hành từ nội dung, UI/UX và frontend đến dữ liệu, tích hợp và hạ tầng production.","seoTitle":"Thiết kế website & phát triển SaaS cho doanh nghiệp — TUNG","seoDescription":"TUNG thiết kế website doanh nghiệp, landing page, CMS và phát triển SaaS full-stack cho doanh nghiệp vừa và nhỏ — từ định hướng đến production.","body":[{"type":"cta","label":"Xem dịch vụ & chi phí","href":"/pricing"},{"type":"cta","label":"Trao đổi dự án","href":"/contact"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_site_section_home_hero_r1');
