INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_site_section_home_hero_r1', 'ja', '{"title":"企業が信頼され、選ばれるウェブサイトを設計し成長を支えるシステムまでつくる。","eyebrow":"ウェブサイト制作 · SaaS開発 · Full-stack","excerpt":"明快なランディングページから複雑なマルチテナントSaaSまで、コンテンツ、UI/UX、frontend、データ、連携、production基盤を一貫して扱います。","seoTitle":"企業ウェブサイト制作・SaaS開発 — TUNG","seoDescription":"TUNGは中小企業向けの企業サイト、LP、CMSを設計し、必要に応じてfull-stack SaaSまで開発します。","body":[{"type":"cta","label":"サービスと料金を見る","href":"/pricing"},{"type":"cta","label":"プロジェクトを相談する","href":"/contact"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_site_section_home_hero_r1');
