INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_project_logivn_r1', 'vi', '{"title":"LogiVN","eyebrow":"F&B SaaS đa tenant","excerpt":"LogiVN kết nối thực đơn QR, tùy chọn món, combo, gọi món, bếp, bàn, đặt chỗ, thanh toán, kho và nhân sự trong cùng một không gian làm việc dành cho quán cà phê và nhà hàng Việt.","seoTitle":"LogiVN — F&B SaaS đa tenant","seoDescription":"LogiVN kết nối thực đơn QR, tùy chọn món, combo, gọi món, bếp, bàn, đặt chỗ, thanh toán, kho và nhân sự trong cùng một không gian làm việc dành cho quán cà phê và nhà hàng Việt.","body":[{"type":"quote","text":"Một vòng vận hành liền mạch từ lượt gọi món qua QR của khách đến bếp, bàn và khu quản trị."},{"type":"paragraph","text":"LogiVN kết nối thực đơn QR, tùy chọn món, combo, gọi món, bếp, bàn, đặt chỗ, thanh toán, kho và nhân sự trong cùng một không gian làm việc dành cho quán cà phê và nhà hàng Việt."},{"type":"heading","text":"Bối cảnh"},{"type":"list","items":["Một nhà hàng không chỉ có một quy trình: khách gọi món, nhân viên tiếp nhận, bếp chuẩn bị, bàn đổi trạng thái và chủ quán vẫn cần một bức tranh vận hành đáng tin cậy.","Khi mỗi bước nằm ở một công cụ khác nhau, việc nhỏ cũng kéo theo nhiều lần xác nhận. LogiVN coi địa điểm kinh doanh là một hệ thống thống nhất, nhưng vẫn giữ giao diện gọn cho từng vai trò.","Sản phẩm phục vụ ba bề mặt chính: trải nghiệm khách, không gian làm việc tại quán và khu quản trị nền tảng."]},{"type":"heading","text":"Quyết định chính"},{"type":"list","items":["Tách trải nghiệm khách, nhân viên và quản trị nền tảng nhưng dùng chung một trạng thái vận hành.","Ưu tiên quyết định tiếp theo thay vì phô ra tất cả trường dữ liệu cùng lúc.","Dùng trạng thái, người phụ trách và thời điểm để làm rõ mọi lần bàn giao."]},{"type":"heading","text":"Kết quả hiện tại"},{"type":"list","items":["Sản phẩm tại logivn.com kết nối gọi món của khách với đội ngũ tại quán trong cùng một không gian.","Một hành trình liền mạch từ QR menu đến bếp, bàn và hoàn tất đơn.","Kho, VietQR và quản trị nền tảng đang tiếp tục được hoàn thiện.","Thiết kế ưu tiên sự rõ ràng cho từng vai trò."]},{"type":"quote","text":"Điều khó không phải thêm một màn hình. Là giữ cho một order, một mô hình quyền hạn và một sự thật vận hành vẫn nhất quán khi có thêm vai trò."},{"type":"cta","label":"Mở LogiVN","href":"https://logivn.com"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_project_logivn_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_project_logivn_r1', 'en', '{"title":"LogiVN","eyebrow":"Multi-tenant F&B SaaS","excerpt":"LogiVN connects QR menus, modifiers, combos, orders, kitchen, tables, reservations, payments, stock and staff tools in one workspace for Vietnamese cafes and restaurants.","seoTitle":"LogiVN — Multi-tenant F&B SaaS","seoDescription":"LogiVN connects QR menus, modifiers, combos, orders, kitchen, tables, reservations, payments, stock and staff tools in one workspace for Vietnamese cafes and restaurants.","body":[{"type":"quote","text":"One clear journey from a guest''s QR order to the kitchen, table and back office."},{"type":"paragraph","text":"LogiVN connects QR menus, modifiers, combos, orders, kitchen, tables, reservations, payments, stock and staff tools in one workspace for Vietnamese cafes and restaurants."},{"type":"heading","text":"Context"},{"type":"list","items":["A restaurant has more than one workflow: guests order, staff receive, the kitchen prepares, tables change state and owners still need a trustworthy view.","When every step lives in a different tool, small changes create repeated coordination work. LogiVN treats the venue as one operating system while keeping each role''s interface focused.","The product has three main surfaces: the guest experience, the venue workspace and the platform control plane."]},{"type":"heading","text":"Key decisions"},{"type":"list","items":["Separate guest, staff and platform-admin experiences while sharing one operational state.","Prioritize the next decision instead of exposing every field at once.","Use status, ownership and timestamps to make every handoff legible."]},{"type":"heading","text":"Current outcomes"},{"type":"list","items":["A public product at logivn.com connecting guest ordering with the venue team in one clear experience.","One clear journey: QR menu → order → kitchen/table → completed service.","Inventory, VietQR payments and platform admin continue to grow on the same foundation.","The product keeps each role focused on the next useful action."]},{"type":"quote","text":"The hard part is not another screen. It is keeping one order, one permission model and one operational truth consistent as more roles arrive."},{"type":"cta","label":"Open LogiVN","href":"https://logivn.com"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_project_logivn_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_project_logivn_r1', 'ja', '{"title":"LogiVN","eyebrow":"マルチテナント F&B SaaS","excerpt":"LogiVNはベトナムのカフェ・飲食店向けに、QRメニュー、注文、キッチン、テーブル、予約、決済、在庫、スタッフ運用を一つのワークスペースにつなぎます。","seoTitle":"LogiVN — マルチテナント F&B SaaS","seoDescription":"LogiVNはベトナムのカフェ・飲食店向けに、QRメニュー、注文、キッチン、テーブル、予約、決済、在庫、スタッフ運用を一つのワークスペースにつなぎます。","body":[{"type":"quote","text":"ゲストのQR注文からキッチン、テーブル、バックオフィスまでを一つの明快な体験にする。"},{"type":"paragraph","text":"LogiVNはベトナムのカフェ・飲食店向けに、QRメニュー、注文、キッチン、テーブル、予約、決済、在庫、スタッフ運用を一つのワークスペースにつなぎます。"},{"type":"heading","text":"背景"},{"type":"list","items":["飲食店には、注文、接客、調理、テーブル管理、経営という複数の流れがあります。","別々のツールに分かれていると、小さな変更にも何度も確認が必要になります。LogiVNは店舗を一つの運用システムとして捉え、役割ごとの画面は軽く保ちます。","ゲスト向け体験、店舗ワークスペース、プラットフォーム管理という三つの面を同じ状態モデルで結びます。"]},{"type":"heading","text":"主な判断"},{"type":"list","items":["ゲスト、スタッフ、プラットフォーム管理を分けつつ、一つの運用状態を共有する。","すべての項目を見せず、次の判断を優先する。","状態、担当、時刻で引き継ぎを明確にする。"]},{"type":"heading","text":"現在の成果"},{"type":"list","items":["logivn.com の公開プロダクトが来客注文と店舗運用を一つの状態モデルでつなぐ。","観察できる中核ループ: QRメニュー → 注文 → キッチン／テーブル → 締め。","在庫、VietQR、管理も同じ基盤の上で広がっています。","役割ごとに、次に必要な操作が明快になるよう設計しています。"]},{"type":"quote","text":"難しいのは画面を増やすことではない。役割が増えても、一つの注文、一つの権限モデル、一つの業務上の事実を保つことだ。"},{"type":"cta","label":"LogiVNを開く","href":"https://logivn.com"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_project_logivn_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_project_logivn_r1', 'zh', '{"title":"LogiVN","eyebrow":"多租户 F&B SaaS","excerpt":"LogiVN面向越南咖啡店和餐厅，将QR菜单、加料、套餐、点单、厨房、餐桌、预订、支付、库存和员工运营放进同一个工作区。","seoTitle":"LogiVN — 多租户 F&B SaaS","seoDescription":"LogiVN面向越南咖啡店和餐厅，将QR菜单、加料、套餐、点单、厨房、餐桌、预订、支付、库存和员工运营放进同一个工作区。","body":[{"type":"quote","text":"从顾客QR点单到厨房、餐桌和后台的一条清晰体验。"},{"type":"paragraph","text":"LogiVN面向越南咖啡店和餐厅，将QR菜单、加料、套餐、点单、厨房、餐桌、预订、支付、库存和员工运营放进同一个工作区。"},{"type":"heading","text":"背景"},{"type":"list","items":["餐厅不只有一种流程：顾客下单，员工接单，厨房制作，餐桌变化，经营者还需要可信的运营视图。","当每一步都在不同工具里时，小变化也会带来重复沟通。LogiVN把门店视为一个运营系统，同时让不同角色的界面保持专注。","产品包含三类主要界面：顾客体验、门店工作区和平台控制面板。"]},{"type":"heading","text":"关键决策"},{"type":"list","items":["分开顾客、员工和平台管理体验，但共享同一运营状态。","优先展示下一步决定，而不是一次显示所有字段。","通过状态、负责人和时间让交接清晰可见。"]},{"type":"heading","text":"当前成果"},{"type":"list","items":["logivn.com 公开产品把顾客点单与门店运营连在同一状态模型上。","可观察的核心循环：QR菜单 → 订单 → 厨房/餐桌 → 收尾。","库存、VietQR 与平台管理也在同一基础上持续丰富。","让每个角色都能清楚看到下一步。"]},{"type":"quote","text":"难点不是再增加一个页面，而是在角色越来越多时，仍然保持同一订单、同一权限模型和同一运营事实。"},{"type":"cta","label":"打开 LogiVN","href":"https://logivn.com"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_project_logivn_r1');
