INSERT OR IGNORE INTO revisions (id, content_item_id, version, status, data_json, created_by, created_at, published_at, slug, sort_order, cover_media_id) SELECT 'seed_project_payment_infrastructure_r1', 'seed_project_payment_infrastructure', 1, 'published', '{"status":"research","statusLabel":"Nghiên cứu sản phẩm","statusLabelVi":"Nghiên cứu sản phẩm","statusLabelEn":"Product study","statusLabelJa":"プロダクトスタディ","statusLabelZh":"产品研究","variant":"payment","research":true}', 'seed:public-content:v1', '2026-07-23T00:00:00.000Z', '2026-07-23T00:00:00.000Z', 'payment-infrastructure', 110, NULL WHERE EXISTS (SELECT 1 FROM content_items WHERE id = 'seed_project_payment_infrastructure');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_project_payment_infrastructure_r1', 'vi', '{"title":"Nghiên cứu xác nhận thanh toán","eyebrow":"Nghiên cứu sản phẩm","excerpt":"Nghiên cứu về cách xác nhận giao dịch, đối soát và gửi thông báo thanh toán đáng tin cậy.","seoTitle":"Nghiên cứu xác nhận thanh toán — Nghiên cứu sản phẩm","seoDescription":"Nghiên cứu về cách xác nhận giao dịch, đối soát và gửi thông báo thanh toán đáng tin cậy.","body":[{"type":"quote","text":"Điều gì phải đúng trước khi tín hiệu giao dịch được phép thay đổi trạng thái của đơn vị bán hàng?"},{"type":"paragraph","text":"Nghiên cứu về cách xác nhận giao dịch, đối soát và gửi thông báo thanh toán đáng tin cậy."},{"type":"heading","text":"Bối cảnh"},{"type":"list","items":["Một màn hình thanh toán đẹp chưa đủ để người dùng hiểu chuyện gì đang xảy ra.","Câu hỏi quan trọng bắt đầu sau tín hiệu chuyển khoản: đối chiếu thế nào, ghi nhận đúng một lần ra sao và thông báo kết quả rõ ràng thế nào.","Mục tiêu là làm cho từng bước dễ theo dõi và giải thích."]},{"type":"heading","text":"Quyết định chính"},{"type":"list","items":["Mọi chuyển trạng thái phải chống trùng lặp.","Tách trạng thái của nhà cung cấp khỏi trạng thái mà đơn vị bán hàng nhìn thấy.","Ghi lại bằng chứng, lịch sử gửi và các lần thử lại thay vì nén tất cả thành một nhãn thành công."]},{"type":"heading","text":"Kết quả hiện tại"},{"type":"list","items":["Mô hình ý định–đối chiếu–xác nhận đủ rõ để thử nghiệm.","Luồng thử lại được thiết kế để tránh lặp hành động.","Thiết kế tập trung vào độ chính xác và khả năng truy vết.","Các nguyên tắc được ghi lại làm cơ sở cho thử nghiệm tiếp theo."]},{"type":"quote","text":"Trong vận hành thanh toán, luồng thuận lợi chỉ là bản trình diễn. Sản phẩm thật nằm ở bằng chứng và cách phục hồi quanh nó."}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_project_payment_infrastructure_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_project_payment_infrastructure_r1', 'en', '{"title":"Payment Confirmation Study","eyebrow":"Product study","excerpt":"A study of how to confirm transactions, reconcile evidence and deliver payment updates people can trust.","seoTitle":"Payment Confirmation Study — Product study","seoDescription":"A study of how to confirm transactions, reconcile evidence and deliver payment updates people can trust.","body":[{"type":"quote","text":"What must be true before a transaction signal can safely change merchant state?"},{"type":"paragraph","text":"A study of how to confirm transactions, reconcile evidence and deliver payment updates people can trust."},{"type":"heading","text":"Context"},{"type":"list","items":["A polished payment screen is only the beginning of a trustworthy experience.","The important question starts after the transfer signal: how to match it, record it once and explain the result clearly.","The study keeps every step clear, traceable and easy to explain."]},{"type":"heading","text":"Key decisions"},{"type":"list","items":["Make every state transition idempotent.","Separate provider state from merchant-visible state.","Keep evidence, delivery history and retries visible instead of collapsing everything into one success label."]},{"type":"heading","text":"Current outcomes"},{"type":"list","items":["A clear model for intent, matching and confirmation.","A retry strategy that keeps the customer experience consistent.","A focused study of accuracy, traceability and customer confidence.","The principles provide a foundation for the next iteration."]},{"type":"quote","text":"In payment operations, the happy path is only the demo. The product is the evidence and recovery model around it."}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_project_payment_infrastructure_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_project_payment_infrastructure_r1', 'ja', '{"title":"決済確認スタディ","eyebrow":"プロダクトスタディ","excerpt":"取引を確認し、照合し、信頼できる更新を届ける体験を研究しています。","seoTitle":"決済確認スタディ — プロダクトスタディ","seoDescription":"取引を確認し、照合し、信頼できる更新を届ける体験を研究しています。","body":[{"type":"quote","text":"取引シグナルが安全に加盟店の状態を変えるために、何が必要か。"},{"type":"paragraph","text":"取引を確認し、照合し、信頼できる更新を届ける体験を研究しています。"},{"type":"heading","text":"背景"},{"type":"list","items":["決済画面がきれいでも、加盟店システムが信頼できる状態を受け取ったとは限りません。","重要なのは送金シグナルの後です。どう照合し、一度だけ記録し、安全に届け、失敗を説明するか。","各ステップを追いやすく、説明しやすい体験にすることを目指します。"]},{"type":"heading","text":"主な判断"},{"type":"list","items":["すべての状態遷移を冪等にする。","プロバイダーの状態と加盟店の状態を分ける。","成功という一つのラベルに圧縮せず、証拠、配信履歴、再試行を見せる。"]},{"type":"heading","text":"現在の成果"},{"type":"list","items":["決済インテント、照合、確認を整理したドメインモデル。","業務アクションを重複させない再試行方針。","正確さ、追跡しやすさ、利用者の安心に焦点を当てたスタディ。","次の検討につながる原則を整理しています。"]},{"type":"quote","text":"決済運用では、成功する道筋はデモにすぎない。本当のプロダクトは、その周りの証拠と復旧モデルにある。"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_project_payment_infrastructure_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_project_payment_infrastructure_r1', 'zh', '{"title":"支付确认研究","eyebrow":"产品研究","excerpt":"研究如何确认交易、核对证据并交付值得信赖的支付更新。","seoTitle":"支付确认研究 — 产品研究","seoDescription":"研究如何确认交易、核对证据并交付值得信赖的支付更新。","body":[{"type":"quote","text":"交易信号在安全改变商户状态之前，必须满足什么条件？"},{"type":"paragraph","text":"研究如何确认交易、核对证据并交付值得信赖的支付更新。"},{"type":"heading","text":"背景"},{"type":"list","items":["支付页面看起来正常，并不代表商户系统收到了可信状态。","真正的问题发生在转账信号之后：如何匹配、只记录一次、安全交付，并解释失败。","让每一步都容易跟踪和解释。"]},{"type":"heading","text":"关键决策"},{"type":"list","items":["让每次状态转换具备幂等性。","分离提供商状态和商户可见状态。","保留证据、交付记录和重试过程，而不是把一切压缩成一个成功标签。"]},{"type":"heading","text":"当前成果"},{"type":"list","items":["更清晰的意图、匹配和确认模型。","不会重复业务动作的重试策略。","聚焦准确性、可追踪性与用户安心的产品研究。","整理出可支持下一轮探索的原则。"]},{"type":"quote","text":"在支付运营里，成功路径只是演示。真正的产品是周围的证据和恢复模型。"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_project_payment_infrastructure_r1');
UPDATE content_items SET status = 'published', current_published_revision_id = 'seed_project_payment_infrastructure_r1' WHERE id = 'seed_project_payment_infrastructure' AND current_published_revision_id IS NULL AND status = 'published' AND version = 1 AND created_at = '2026-07-23T00:00:00.000Z' AND updated_at = '2026-07-23T00:00:00.000Z';

