INSERT OR IGNORE INTO content_items (id, type, slug, status, sort_order, cover_media_id, meta_json, version, current_published_revision_id, created_at, updated_at, deleted_at) VALUES ('seed_project_fball', 'project', 'fball', 'published', 120, NULL, '{"status":"active","statusLabel":"Đã ra mắt","statusLabelVi":"Đã ra mắt","statusLabelEn":"Launched","statusLabelJa":"公開中","statusLabelZh":"已上线","variant":"fball","research":false,"liveUrl":"https://fball.vn"}', 1, 'seed_project_fball_r1', '2026-07-23T00:00:00.000Z', '2026-07-23T00:00:00.000Z', NULL);
INSERT OR IGNORE INTO revisions (id, content_item_id, version, status, data_json, created_by, created_at, published_at, slug, sort_order, cover_media_id) SELECT 'seed_project_fball_r1', 'seed_project_fball', 1, 'published', '{"status":"active","statusLabel":"Đã ra mắt","statusLabelVi":"Đã ra mắt","statusLabelEn":"Launched","statusLabelJa":"公開中","statusLabelZh":"已上线","variant":"fball","research":false,"liveUrl":"https://fball.vn"}', 'seed:public-content:v1', '2026-07-23T00:00:00.000Z', '2026-07-23T00:00:00.000Z', 'fball', 120, NULL WHERE EXISTS (SELECT 1 FROM content_items WHERE id = 'seed_project_fball');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_project_fball_r1', 'vi', '{"title":"Fball.vn","eyebrow":"Hệ thống vận hành đội bóng phong trào","excerpt":"Fball kết nối vận hành đội bóng — lịch, điểm danh, đội hình, thành viên, quyền hạn và quỹ đội — với các bề mặt công khai để tìm đội, ghép trận và khám phá sân bóng.","seoTitle":"Fball.vn — Hệ thống vận hành đội bóng phong trào","seoDescription":"Fball kết nối vận hành đội bóng — lịch, điểm danh, đội hình, thành viên, quyền hạn và quỹ đội — với các bề mặt công khai để tìm đội, ghép trận và khám phá sân bóng.","body":[{"type":"quote","text":"Biến một trận bóng rời rạc thành nhịp vận hành có thể lặp lại cho cả đội."},{"type":"paragraph","text":"Fball kết nối vận hành đội bóng — lịch, điểm danh, đội hình, thành viên, quyền hạn và quỹ đội — với các bề mặt công khai để tìm đội, ghép trận và khám phá sân bóng."},{"type":"heading","text":"Bối cảnh"},{"type":"list","items":["Trước mỗi trận, đội trưởng cần ba câu trả lời: đá lúc nào, ai đi và chia đội thế nào. Những thông tin này thường nằm rải trong các chuỗi tin nhắn dài và danh sách ghép thủ công.","Fball tạo không gian làm việc riêng cho từng đội, biến việc phối hợp lặp lại thành trạng thái dễ nhìn thấy mà vẫn giữ nhịp linh hoạt của bóng đá phong trào.","Các bề mặt công khai để tìm đội, ghép trận và khám phá sân bóng kết nối với không gian riêng của từng đội."]},{"type":"heading","text":"Quyết định chính"},{"type":"list","items":["Biến điểm danh thành trạng thái dùng chung, không phải thêm một tin nhắn trong nhóm.","Xây vòng lặp ngày thi đấu trước khi mở rộng thành nền tảng.","Giữ vai trò đội trưởng khác với trải nghiệm đơn giản của thành viên; mọi tự động hóa đều cần bước xác nhận."]},{"type":"heading","text":"Kết quả hiện tại"},{"type":"list","items":["Sản phẩm tại fball.vn giúp các đội bóng phong trào Việt Nam phối hợp trước và trong ngày thi đấu.","Một không gian chung cho lịch, điểm danh, đội hình, thành viên, phân quyền và sổ quỹ.","Các trang tìm đội, ghép trận và sân bóng mở rộng trải nghiệm ra ngoài không gian riêng của từng đội.","Thiết kế tập trung vào việc giúp đội trưởng và thành viên phối hợp nhanh hơn."]},{"type":"quote","text":"Thử thách không phải thêm màn hình. Là giữ cho đội, quyền và trạng thái đúng khi một công cụ ngày thi đấu mở rộng sang tài chính, ghép trận và tự động hóa."},{"type":"cta","label":"Mở Fball.vn","href":"https://fball.vn"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_project_fball_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_project_fball_r1', 'en', '{"title":"Fball.vn","eyebrow":"Club OS for grassroots football","excerpt":"Fball connects club operations — schedules, attendance, lineups, members, permissions and the team fund — with live public discovery for finding teams, arranging matches and browsing venues.","seoTitle":"Fball.vn — Club OS for grassroots football","seoDescription":"Fball connects club operations — schedules, attendance, lineups, members, permissions and the team fund — with live public discovery for finding teams, arranging matches and browsing venues.","body":[{"type":"quote","text":"Turn a scattered match plan into a repeatable rhythm for the whole team."},{"type":"paragraph","text":"Fball connects club operations — schedules, attendance, lineups, members, permissions and the team fund — with live public discovery for finding teams, arranging matches and browsing venues."},{"type":"heading","text":"Context"},{"type":"list","items":["Before a match, a captain needs three answers: when are we playing, who is coming and how will the squad be split. Those answers often live across long chat threads and hand-built lists.","Fball gives each club its own workspace, making recurring coordination visible while preserving the flexibility of grassroots football.","Public surfaces for finding teams, arranging matches and browsing venues connect with each club workspace."]},{"type":"heading","text":"Key decisions"},{"type":"list","items":["Make attendance shared state, not another chat message.","Build the match-day loop before expanding the platform.","Keep captain controls distinct from the member experience and require confirmation for automation."]},{"type":"heading","text":"Current outcomes"},{"type":"list","items":["A public product at fball.vn that helps Vietnamese grassroots clubs plan and play together.","One shared space for schedules, attendance, lineups, membership, permissions and the team fund.","Finding teams, arranging matches and browsing venues extend the experience beyond the club workspace.","The product keeps captains and members focused on the next useful action."]},{"type":"quote","text":"The challenge is not adding screens. It is keeping teams, permissions and state correct as a match-day tool grows into finance, discovery and automation."},{"type":"cta","label":"Open Fball.vn","href":"https://fball.vn"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_project_fball_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_project_fball_r1', 'ja', '{"title":"Fball.vn","eyebrow":"草サッカークラブ運営システム","excerpt":"Fballは予定、出欠、ラインナップ、メンバー、権限、チーム会計というクラブ運営と、チーム探し、対戦調整、会場探しの公開機能をつなぎます。","seoTitle":"Fball.vn — 草サッカークラブ運営システム","seoDescription":"Fballは予定、出欠、ラインナップ、メンバー、権限、チーム会計というクラブ運営と、チーム探し、対戦調整、会場探しの公開機能をつなぎます。","body":[{"type":"quote","text":"散らばった試合準備を、チーム全体で共有できる体験に変える。"},{"type":"paragraph","text":"Fballは予定、出欠、ラインナップ、メンバー、権限、チーム会計というクラブ運営と、チーム探し、対戦調整、会場探しの公開機能をつなぎます。"},{"type":"heading","text":"背景"},{"type":"list","items":["試合前に必要なのは、いつ、誰が来るか、どう分けるかの三つです。実際には長いチャットと手作業のリストに分かれています。","Fballはクラブごとのワークスペースをつくり、草サッカーの柔軟さを残したまま、繰り返す調整を見える状態にします。","チーム探し、対戦調整、会場探しの公開機能が、クラブごとのワークスペースにつながっています。"]},{"type":"heading","text":"主な判断"},{"type":"list","items":["出欠を共有状態にし、チャットの一文にしない。","プラットフォームを広げる前に、試合当日のループを完成させる。","キャプテン操作とメンバー体験を分け、自動化には確認を求める。"]},{"type":"heading","text":"現在の成果"},{"type":"list","items":["fball.vn は、草サッカークラブが試合までの準備を共有できる公開プロダクトです。","予定、出欠、ラインナップ、メンバー、権限、会計をつなぐコア体験。","チーム探し、対戦調整、会場探しがクラブ体験を外へ広げます。","キャプテンとメンバーが次の行動に集中できる設計です。"]},{"type":"quote","text":"課題は画面を増やすことではない。試合日ツールが会計、対戦相手探し、自動化へ広がっても、チーム、権限、状態を正しく保つことだ。"},{"type":"cta","label":"Fball.vnを開く","href":"https://fball.vn"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_project_fball_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_project_fball_r1', 'zh', '{"title":"Fball.vn","eyebrow":"草根足球俱乐部运营系统","excerpt":"Fball把日程、出勤、阵容、成员、权限和球队资金等俱乐部运营，与找球队、约比赛和查找球场的公开功能连接起来。","seoTitle":"Fball.vn — 草根足球俱乐部运营系统","seoDescription":"Fball把日程、出勤、阵容、成员、权限和球队资金等俱乐部运营，与找球队、约比赛和查找球场的公开功能连接起来。","body":[{"type":"quote","text":"把分散的比赛计划变成整支球队可以共享的体验。"},{"type":"paragraph","text":"Fball把日程、出勤、阵容、成员、权限和球队资金等俱乐部运营，与找球队、约比赛和查找球场的公开功能连接起来。"},{"type":"heading","text":"背景"},{"type":"list","items":["比赛前，队长需要三个答案：什么时候踢、谁会来、如何分组。这些信息往往散落在很长的聊天记录和手工名单里。","Fball为每个俱乐部提供独立工作区，在保留草根足球灵活性的同时，让重复协调变成看得见的状态。","找球队、约比赛和查找球场的公开功能与各俱乐部工作区相连。"]},{"type":"heading","text":"关键决策"},{"type":"list","items":["把出勤变成共享状态，而不是聊天中的一句话。","先完成比赛日核心循环，再扩展为平台。","区分队长控制与成员体验，自动化变更必须经过确认。"]},{"type":"heading","text":"当前成果"},{"type":"list","items":["fball.vn 是帮助越南草根俱乐部共同准备和比赛的公开产品。","覆盖日程、出勤、阵容、成员、权限和球队账本的核心循环。","找球队、约比赛和查找球场让体验延伸到俱乐部工作区之外。","让队长与成员专注于下一步。"]},{"type":"quote","text":"挑战不是增加页面，而是在比赛日工具扩展到财务、约球和自动化后，仍然保证球队、权限和状态正确。"},{"type":"cta","label":"打开 Fball.vn","href":"https://fball.vn"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_project_fball_r1');
UPDATE content_items SET status = 'published', current_published_revision_id = 'seed_project_fball_r1' WHERE id = 'seed_project_fball' AND current_published_revision_id IS NULL AND status = 'published' AND version = 1 AND created_at = '2026-07-23T00:00:00.000Z' AND updated_at = '2026-07-23T00:00:00.000Z';

