INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_payment_confirmation_reconciliation_r1', 'vi', '{"title":"Xác nhận và đối soát thanh toán","eyebrow":"Nền tảng","excerpt":"Bắt đầu từ quy tắc đối chiếu rõ ràng, cập nhật một lần và lịch sử dễ theo dõi.","seoTitle":"Xác nhận và đối soát thanh toán — Tung","seoDescription":"Bắt đầu từ quy tắc đối chiếu rõ ràng, cập nhật một lần và lịch sử dễ theo dõi.","body":[{"type":"heading","text":"Câu hỏi"},{"type":"paragraph","text":"Điều gì giúp một tín hiệu thanh toán trở nên đáng tin cậy?"},{"type":"heading","text":"Vì sao đáng quan tâm"},{"type":"paragraph","text":"Một trải nghiệm thanh toán tốt cần rõ ràng ngay cả khi kết nối hoặc dịch vụ bên ngoài gặp trục trặc."},{"type":"heading","text":"Kết luận hiện tại"},{"type":"quote","text":"Bắt đầu từ quy tắc đối chiếu rõ ràng, cập nhật một lần và lịch sử dễ theo dõi."},{"type":"cta","label":"Xem nghiên cứu vận hành thanh toán","href":"/work/payment-infrastructure"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_payment_confirmation_reconciliation_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_payment_confirmation_reconciliation_r1', 'en', '{"title":"Clear payment confirmation","eyebrow":"Product systems","excerpt":"Start with clear matching rules, one-time updates and a history people can follow.","seoTitle":"Clear payment confirmation — Tung","seoDescription":"Start with clear matching rules, one-time updates and a history people can follow.","body":[{"type":"heading","text":"Question"},{"type":"paragraph","text":"What makes a payment update clear and trustworthy for customers and merchants?"},{"type":"heading","text":"Why it matters"},{"type":"paragraph","text":"A good experience needs one clear answer even when an external service is slow or unavailable."},{"type":"heading","text":"Current conclusion"},{"type":"quote","text":"Start with clear matching rules, one-time updates and a history people can follow."},{"type":"cta","label":"Read the payment operations research","href":"/work/payment-infrastructure"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_payment_confirmation_reconciliation_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_payment_confirmation_reconciliation_r1', 'ja', '{"title":"わかりやすい決済確認","eyebrow":"プロダクト基盤","excerpt":"明確な照合ルール、一度だけの更新、追いやすい履歴から始めます。","seoTitle":"わかりやすい決済確認 — Tung","seoDescription":"明確な照合ルール、一度だけの更新、追いやすい履歴から始めます。","body":[{"type":"heading","text":"問い"},{"type":"paragraph","text":"利用者と店舗の双方にとって、信頼できる決済更新とは何か。"},{"type":"heading","text":"なぜ重要か"},{"type":"paragraph","text":"外部サービスが遅い時でも、答えが一つにまとまる体験が必要です。"},{"type":"heading","text":"現在の結論"},{"type":"quote","text":"明確な照合ルール、一度だけの更新、追いやすい履歴から始めます。"},{"type":"cta","label":"決済運用リサーチを見る","href":"/work/payment-infrastructure"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_payment_confirmation_reconciliation_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_payment_confirmation_reconciliation_r1', 'zh', '{"title":"清晰的支付确认","eyebrow":"产品基础","excerpt":"从清晰的匹配规则、一次性更新和易于追踪的记录开始。","seoTitle":"清晰的支付确认 — Tung","seoDescription":"从清晰的匹配规则、一次性更新和易于追踪的记录开始。","body":[{"type":"heading","text":"问题"},{"type":"paragraph","text":"怎样的支付更新，能让客户与商户都清楚且放心？"},{"type":"heading","text":"为什么重要"},{"type":"paragraph","text":"即使外部服务变慢或暂时不可用，良好的体验也需要给出一个明确答案。"},{"type":"heading","text":"当前结论"},{"type":"quote","text":"从清晰的匹配规则、一次性更新和易于追踪的记录开始。"},{"type":"cta","label":"查看支付运营研究","href":"/work/payment-infrastructure"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_payment_confirmation_reconciliation_r1');
