INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_tenant_boundaries_in_practice_r1', 'vi', '{"title":"Quyền truy cập rõ ràng cho mọi không gian làm việc","eyebrow":"Sản phẩm","excerpt":"Thiết kế vai trò và quyền hạn như một phần của sản phẩm, để mỗi người có đúng thông tin cần thiết.","seoTitle":"Quyền truy cập rõ ràng cho mọi không gian làm việc — Tung","seoDescription":"Thiết kế vai trò và quyền hạn như một phần của sản phẩm, để mỗi người có đúng thông tin cần thiết.","body":[{"type":"heading","text":"Câu hỏi"},{"type":"paragraph","text":"Làm sao để mỗi người luôn thấy đúng phần việc của mình?"},{"type":"heading","text":"Vì sao đáng quan tâm"},{"type":"paragraph","text":"LogiVN và Fball phục vụ nhiều đội, nên trải nghiệm tốt bắt đầu từ những ranh giới dễ hiểu."},{"type":"heading","text":"Kết luận hiện tại"},{"type":"quote","text":"Thiết kế vai trò và quyền hạn như một phần của sản phẩm, để mỗi người có đúng thông tin cần thiết."}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_tenant_boundaries_in_practice_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_tenant_boundaries_in_practice_r1', 'en', '{"title":"Clear access for every workspace","eyebrow":"Product design","excerpt":"Treat roles and access as part of the product so each person sees the information they need.","seoTitle":"Clear access for every workspace — Tung","seoDescription":"Treat roles and access as part of the product so each person sees the information they need.","body":[{"type":"heading","text":"Question"},{"type":"paragraph","text":"How can each person see the right work without extra friction?"},{"type":"heading","text":"Why it matters"},{"type":"paragraph","text":"LogiVN and Fball serve many teams, so a good experience begins with access that feels obvious."},{"type":"heading","text":"Current conclusion"},{"type":"quote","text":"Treat roles and access as part of the product so each person sees the information they need."}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_tenant_boundaries_in_practice_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_tenant_boundaries_in_practice_r1', 'ja', '{"title":"ワークスペースごとの明確なアクセス","eyebrow":"プロダクト設計","excerpt":"役割とアクセスをプロダクトの一部として設計し、必要な情報だけを届けます。","seoTitle":"ワークスペースごとの明確なアクセス — Tung","seoDescription":"役割とアクセスをプロダクトの一部として設計し、必要な情報だけを届けます。","body":[{"type":"heading","text":"問い"},{"type":"paragraph","text":"余計な手間を増やさず、必要な仕事だけを見せるにはどうするか。"},{"type":"heading","text":"なぜ重要か"},{"type":"paragraph","text":"LogiVNとFballは多くのチームを扱うため、わかりやすいアクセス設計が体験の土台になります。"},{"type":"heading","text":"現在の結論"},{"type":"quote","text":"役割とアクセスをプロダクトの一部として設計し、必要な情報だけを届けます。"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_tenant_boundaries_in_practice_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_tenant_boundaries_in_practice_r1', 'zh', '{"title":"每个工作区都清楚的访问方式","eyebrow":"产品设计","excerpt":"把角色与访问作为产品的一部分，让每个人看到真正需要的信息。","seoTitle":"每个工作区都清楚的访问方式 — Tung","seoDescription":"把角色与访问作为产品的一部分，让每个人看到真正需要的信息。","body":[{"type":"heading","text":"问题"},{"type":"paragraph","text":"如何不增加额外步骤，让每个人只看到真正相关的工作？"},{"type":"heading","text":"为什么重要"},{"type":"paragraph","text":"LogiVN与Fball服务多个团队，因此清楚自然的访问方式是体验基础。"},{"type":"heading","text":"当前结论"},{"type":"quote","text":"把角色与访问作为产品的一部分，让每个人看到真正需要的信息。"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_tenant_boundaries_in_practice_r1');
