INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_low_cost_cloud_operations_r1', 'vi', '{"title":"Nền tảng gọn cho sản phẩm nhỏ","eyebrow":"Nền tảng","excerpt":"Ưu tiên những thành phần đơn giản, giới hạn rõ và có thể thay đổi khi nhu cầu đã rõ hơn.","seoTitle":"Nền tảng gọn cho sản phẩm nhỏ — Tung","seoDescription":"Ưu tiên những thành phần đơn giản, giới hạn rõ và có thể thay đổi khi nhu cầu đã rõ hơn.","body":[{"type":"heading","text":"Câu hỏi"},{"type":"paragraph","text":"Một sản phẩm nhỏ cần nền tảng đến đâu để có thể lớn lên tự nhiên?"},{"type":"heading","text":"Vì sao đáng quan tâm"},{"type":"paragraph","text":"Giai đoạn đầu cần đủ linh hoạt để thay đổi mà không bị gánh nặng công nghệ kéo chậm."},{"type":"heading","text":"Kết luận hiện tại"},{"type":"quote","text":"Ưu tiên những thành phần đơn giản, giới hạn rõ và có thể thay đổi khi nhu cầu đã rõ hơn."}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_low_cost_cloud_operations_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_low_cost_cloud_operations_r1', 'en', '{"title":"A lean foundation for small products","eyebrow":"Product systems","excerpt":"Prefer simple building blocks with clear limits, then add complexity when the product earns it.","seoTitle":"A lean foundation for small products — Tung","seoDescription":"Prefer simple building blocks with clear limits, then add complexity when the product earns it.","body":[{"type":"heading","text":"Question"},{"type":"paragraph","text":"What does a small product need today so it can keep growing tomorrow?"},{"type":"heading","text":"Why it matters"},{"type":"paragraph","text":"Early products need room to change without carrying unnecessary complexity."},{"type":"heading","text":"Current conclusion"},{"type":"quote","text":"Prefer simple building blocks with clear limits, then add complexity when the product earns it."}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_low_cost_cloud_operations_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_low_cost_cloud_operations_r1', 'ja', '{"title":"小さなプロダクトのための軽やかな基盤","eyebrow":"プロダクト基盤","excerpt":"限界が明確なシンプルな部品から始め、必要になった時だけ複雑さを加えます。","seoTitle":"小さなプロダクトのための軽やかな基盤 — Tung","seoDescription":"限界が明確なシンプルな部品から始め、必要になった時だけ複雑さを加えます。","body":[{"type":"heading","text":"問い"},{"type":"paragraph","text":"今は小さなプロダクトが、明日も成長するために必要なものは何か。"},{"type":"heading","text":"なぜ重要か"},{"type":"paragraph","text":"初期のプロダクトには、余計な複雑さを抱えずに方向を変えられる余白が必要です。"},{"type":"heading","text":"現在の結論"},{"type":"quote","text":"限界が明確なシンプルな部品から始め、必要になった時だけ複雑さを加えます。"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_low_cost_cloud_operations_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_low_cost_cloud_operations_r1', 'zh', '{"title":"适合小型产品的轻量基础","eyebrow":"产品基础","excerpt":"先用边界清晰的简单组件，产品真正需要时再增加复杂性。","seoTitle":"适合小型产品的轻量基础 — Tung","seoDescription":"先用边界清晰的简单组件，产品真正需要时再增加复杂性。","body":[{"type":"heading","text":"问题"},{"type":"paragraph","text":"一个小型产品今天需要什么，才能在明天继续成长？"},{"type":"heading","text":"为什么重要"},{"type":"paragraph","text":"早期产品需要改变方向的空间，而不是过早背上不必要的复杂度。"},{"type":"heading","text":"当前结论"},{"type":"quote","text":"先用边界清晰的简单组件，产品真正需要时再增加复杂性。"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_low_cost_cloud_operations_r1');
