INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_assisted_operations_with_confirmation_r1', 'vi', '{"title":"AI hỗ trợ với bước xác nhận","eyebrow":"Sản phẩm","excerpt":"Dùng AI cho đề xuất, tóm tắt và trích xuất; người dùng luôn là người xác nhận thay đổi cuối cùng.","seoTitle":"AI hỗ trợ với bước xác nhận — Tung","seoDescription":"Dùng AI cho đề xuất, tóm tắt và trích xuất; người dùng luôn là người xác nhận thay đổi cuối cùng.","body":[{"type":"heading","text":"Câu hỏi"},{"type":"paragraph","text":"AI có thể giúp giảm việc lặp lại mà vẫn giữ quyền quyết định cho con người ở đâu?"},{"type":"heading","text":"Vì sao đáng quan tâm"},{"type":"paragraph","text":"Gợi ý đúng lúc có thể giúp đội ngũ nhẹ việc hơn, nhưng quyết định quan trọng vẫn cần người xem lại."},{"type":"heading","text":"Kết luận hiện tại"},{"type":"quote","text":"Dùng AI cho đề xuất, tóm tắt và trích xuất; người dùng luôn là người xác nhận thay đổi cuối cùng."}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_assisted_operations_with_confirmation_r1');
